"""Regenerate the standalone render fixture after changing the homepage."""
from pathlib import Path
root = Path(__file__).resolve().parents[1]
instrument = '<base href="../"><script>\nhistory.replaceState(null,\'\',new URL(\'../index.html?qa=performance\',location.href).href);\nconst qaMetrics={fcp:null,lcp:null,cls:0,shifts:[]};\nconst qaLcp=new PerformanceObserver(list=>{for(const e of list.getEntries())qaMetrics.lcp=e.startTime});qaLcp.observe({type:\'largest-contentful-paint\',buffered:true});\nconst qaCls=new PerformanceObserver(list=>{qaMetrics.shifts.push(...list.getEntries().filter(e=>!e.hadRecentInput).map(e=>({value:e.value,time:e.startTime,nodes:e.sources?.map(s=>s.node?.tagName+\'.\'+s.node?.className)})))});qaCls.observe({type:\'layout-shift\',buffered:true});\nwindow.addEventListener(\'load\',()=>setTimeout(()=>{qaMetrics.fcp=performance.getEntriesByType(\'paint\').find(e=>e.name===\'first-contentful-paint\')?.startTime??null;let score=0,first=0,last=0;for(const e of qaMetrics.shifts){if(e.time-last>1000||e.time-first>5000){score=0;first=e.time}score+=e.value;last=e.time;qaMetrics.cls=Math.max(qaMetrics.cls,score)}qaLcp.disconnect();qaCls.disconnect();const out=document.createElement(\'pre\');out.id=\'qa-metrics\';out.style.cssText=\'position:fixed;right:8px;top:8px;z-index:100;max-width:300px;max-height:80vh;overflow:auto;padding:12px;background:#fff;border:1px solid #8792a3;font:12px/1.5 monospace;box-shadow:0 4px 20px #0002\';out.textContent=JSON.stringify(qaMetrics,null,2);document.body.append(out)},2000));\n</script>'
(root/'tests/performance.html').write_text((root/'index.html').read_text().replace('<head>','<head>'+instrument))
